import time
import numpy as np
from scipy import sparse
from scipy.sparse.linalg import eigs

def make(n=300, seed=1, density=0.01):
    rng = np.random.default_rng(seed)
    return sparse.random(n, n, density=density, format="csr", data_rvs=rng.standard_normal)

def solve_ref(A, k=5):
    N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    eigenvalues, eigenvectors = eigs(A, k=k, v0=v0, maxiter=N*200, ncv=max(2*k+1, 20))
    pairs = list(zip(eigenvalues, eigenvectors.T))
    pairs.sort(key=lambda pair: -np.abs(pair[0]))
    return [p[1] for p in pairs], [p[0] for p in pairs]

def solve_fast(A, k=5, ncv=20, tol=0):
    N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    kwargs=dict(k=k, v0=v0, maxiter=N*200, ncv=ncv)
    if tol:
        kwargs['tol']=tol
    eigenvalues, eigenvectors = eigs(A, **kwargs)
    pairs = list(zip(eigenvalues, eigenvectors.T))
    pairs.sort(key=lambda pair: -np.abs(pair[0]))
    return [p[1] for p in pairs], [p[0] for p in pairs]

def sim(exp, cand):
    return abs(np.vdot(exp, cand)) / (np.linalg.norm(exp)*np.linalg.norm(cand))

# time comparison over 10 seeds
seeds=list(range(10))
As=[make(seed=s) for s in seeds]

def timeit(fn, reps=3):
    # warmup
    fn()
    ts=[]
    for _ in range(reps):
        t0=time.perf_counter()
        fn()
        ts.append(time.perf_counter()-t0)
    return min(ts)

def run_all(solver):
    for A in As:
        solver(A)

print("ref", timeit(lambda: run_all(solve_ref)))
for ncv in [12,15,16,18,20,24,30]:
    for tol in [0, 1e-10, 1e-8]:
        def s(A, ncv=ncv, tol=tol):
            return solve_fast(A, ncv=ncv, tol=tol)
        try:
            t=timeit(lambda: run_all(s))
        except Exception as e:
            print("ncv", ncv, "tol", tol, "ERR", e)
            continue
        # accuracy
        fails=0
        worst=1
        for A in As:
            exp,_=solve_ref(A)
            cand,_=s(A)
            sims=[sim(e,c) for e,c in zip(exp,cand)]
            worst=min(worst, min(sims))
            if min(sims) < 1-1e-6:
                fails+=1
        print(f"ncv={ncv:2d} tol={tol:.0e} time={t:.4f} speedup={timeit(lambda: run_all(solve_ref))/t:.2f} fails={fails} worst={worst:.8f}")
EOF"}

