import time
import numpy as np
from scipy.sparse.linalg import eigs
from reference import Task

task=Task()
problems=[task.generate_problem(300, random_seed=s) for s in range(6)]

def ref_solve(p):
    return task.solve(p)

def try_solve(A, k=5, ncv=20, tol=0, v0=None, maxiter=None):
    N=A.shape[0]
    if v0 is None:
        v0=np.ones(N, dtype=A.dtype)
    kw=dict(k=k, v0=v0, ncv=ncv, maxiter=maxiter or N*200)
    if tol:
        kw['tol']=tol
    vals, vecs=eigs(A, **kw)
    order=np.argsort(-np.abs(vals))
    return [vecs[:,i] for i in order]

def sim_set(sol, exp):
    # greedy match
    used=set()
    sims=[]
    for c in sol:
        best=0; bi=None
        nc=np.linalg.norm(c)
        for i,e in enumerate(exp):
            if i in used: continue
            s=abs(np.vdot(e,c))/(np.linalg.norm(e)*nc)
            if s>best:
                best=s; bi=i
        used.add(bi)
        sims.append(best)
    return min(sims)

for i,p in enumerate(problems):
    A=p["matrix"]
    exp=ref_solve(p)
    print("seed", i)
    for ncv in [20, 30, 40, 60]:
        for tol in [0, 1e-8]:
            t0=time.perf_counter()
            try:
                sol=try_solve(A, ncv=ncv, tol=tol)
                dt=time.perf_counter()-t0
                ms=sim_set(sol, exp)
                # also ordered similarity
                ordered=min(abs(np.vdot(e,c))/(np.linalg.norm(e)*np.linalg.norm(c)) for e,c in zip(exp,sol))
                print(f"  ncv={ncv} tol={tol:.0e} t={dt:.3f} setmin={ms:.4f} ordmin={ordered:.4f}")
            except Exception as e:
                print(f"  ncv={ncv} tol={tol} ERR {type(e).__name__}")
