#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>
#include <complex.h>

/* ARNAUD reverse-communication interface (arpack-ng / scipy ARNAUD).
   Signature inferred from arnaud/arnaud_d.h. We will adjust if needed.
*/

typedef void (*dnaupd_fn)(
    int *ido, char *bmat, int *n, char *which, int *nev, double *tol,
    double *resid, int *ncv, double *v, int *ldv, int *iparam, int *ipntr,
    double *workd, double *workl, int *lworkl, int *info);

typedef void (*dneupd_fn)(
    int *rvec, char *howmny, int *select, double *dr, double *di,
    double *z, int *ldz, double *sigmar, double *sigmai, double *workev,
    char *bmat, int *n, char *which, int *nev, double *tol, double *resid,
    int *ncv, double *v, int *ldv, int *iparam, int *ipntr, double *workd,
    double *workl, int *lworkl, int *info);

static dnaupd_fn dnaupd = NULL;
static dneupd_fn dneupd = NULL;

static void csr_matvec(int n, const int *indptr, const int *indices, const double *data,
                       const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        int s = indptr[i];
        int e = indptr[i + 1];
        double acc = 0.0;
        for (int j = s; j < e; j++) {
            acc += data[j] * x[indices[j]];
        }
        y[i] = acc;
    }
}

static PyObject *solve(PyObject *self, PyObject *args) {
    PyObject *indptr_o, *indices_o, *data_o, *v0_o;
    int k, ncv, maxiter;
    double tol;
    if (!PyArg_ParseTuple(args, "OOOOiiid", &indptr_o, &indices_o, &data_o, &v0_o,
                          &k, &ncv, &maxiter, &tol)) {
        return NULL;
    }
    PyArrayObject *indptr = (PyArrayObject *)PyArray_FROM_OTF(indptr_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices = (PyArrayObject *)PyArray_FROM_OTF(indices_o, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *data = (PyArrayObject *)PyArray_FROM_OTF(data_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *v0 = (PyArrayObject *)PyArray_FROM_OTF(v0_o, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!indptr || !indices || !data || !v0) {
        Py_XDECREF(indptr); Py_XDECREF(indices); Py_XDECREF(data); Py_XDECREF(v0);
        return NULL;
    }
    int n = (int)PyArray_DIM(v0, 0);
    int *ip = (int *)PyArray_DATA(indptr);
    int *ix = (int *)PyArray_DATA(indices);
    double *ax = (double *)PyArray_DATA(data);
    double *v0d = (double *)PyArray_DATA(v0);

    int ido = 0;
    char bmat = 'I';
    char which[3] = {'L', 'M', '\0'};
    int nev = k;
    int ldv = n;
    int mode = 1;
    int info = 1; /* use resid as start */
    int iparam[11];
    memset(iparam, 0, sizeof(iparam));
    iparam[0] = 1;          /* ishift */
    iparam[2] = maxiter;    /* mxiter */
    iparam[3] = 1;          /* NB */
    iparam[6] = mode;

    int ipntr[14];
    memset(ipntr, 0, sizeof(ipntr));

    double *resid = (double *)malloc(sizeof(double) * n);
    memcpy(resid, v0d, sizeof(double) * n);
    /* V is column-major n x ncv */
    double *V = (double *)calloc((size_t)n * ncv, sizeof(double));
    double *workd = (double *)calloc(3 * n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc(lworkl, sizeof(double));

    int iter_guard = maxiter * ncv + 100;
    int calls = 0;
    while (calls < iter_guard) {
        dnaupd(&ido, &bmat, &n, which, &nev, &tol, resid, &ncv, V, &ldv,
               iparam, ipntr, workd, workl, &lworkl, &info);
        calls++;
        if (ido == 1 || ido == -1) {
            /* ipntr is 1-based */
            int xoff = ipntr[0] - 1;
            int yoff = ipntr[1] - 1;
            csr_matvec(n, ip, ix, ax, workd + xoff, workd + yoff);
        } else if (ido == 2) {
            int xoff = ipntr[0] - 1;
            int yoff = ipntr[1] - 1;
            memcpy(workd + yoff, workd + xoff, sizeof(double) * n);
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
    }

    int nconv = iparam[4];
    int rvec = 1;
    char howmny = 'A';
    int *select = (int *)calloc(ncv, sizeof(int));
    double *dr = (double *)calloc(nev + 1, sizeof(double));
    double *di = (double *)calloc(nev + 1, sizeof(double));
    double *z = (double *)calloc((size_t)n * (nev + 1), sizeof(double));
    double sigmar = 0, sigmai = 0;
    double *workev = (double *)calloc(3 * ncv, sizeof(double));
    int info2 = 0;
    dneupd(&rvec, &howmny, select, dr, di, z, &ldv, &sigmar, &sigmai, workev,
           &bmat, &n, which, &nev, &tol, resid, &ncv, V, &ldv, iparam, ipntr,
           workd, workl, &lworkl, &info2);
    nconv = iparam[4];

    /* Build complex eigenvectors like scipy: consecutive real/imag columns */
    npy_intp dims_v[1] = {nev + 1};
    PyArrayObject *evals = (PyArrayObject *)PyArray_SimpleNew(1, dims_v, NPY_COMPLEX128);
    npy_intp dims_z[2] = {n, nev + 1};
    PyArrayObject *evecs = (PyArrayObject *)PyArray_SimpleNew(2, dims_z, NPY_COMPLEX128);
    double complex *ed = (double complex *)PyArray_DATA(evals);
    double complex *zd = (double complex *)PyArray_DATA(evecs);
    for (int i = 0; i <= nev; i++) {
        ed[i] = dr[i] + I * di[i];
    }
    /* copy z as real first */
    for (int col = 0; col <= nev; col++) {
        for (int row = 0; row < n; row++) {
            zd[row + (npy_intp)col * n] = z[row + (size_t)col * n] + 0.0 * I;
        }
    }
    for (int i = 0; i <= nev; i++) {
        if (cabs(ed[i] - conj(ed[i])) > 0) { /* imag != 0, i.e. complex */
            if (i < nev) {
                for (int row = 0; row < n; row++) {
                    double re = z[row + (size_t)i * n];
                    double im = z[row + (size_t)(i + 1) * n];
                    zd[row + (npy_intp)i * n] = re + I * im;
                    zd[row + (npy_intp)(i + 1) * n] = re - I * im;
                }
                i++;
            }
